/* ===== Kazakh display name normalizer for university names ===== */
window.kazifyUni = (function(){
function kazifyUni(s){
  if(!s) return s;
  var str=String(s).trim();
  var head=str.split('(')[0];
  var headKZ=/[ӘәҒғҚқҢңӨөҰұҮүҺһІі]/.test(head);
  var paren=str.match(/\(([^)]*[А-Яа-яЁё][^)]*)\)\s*$/);
  if(paren && /[A-Za-z]/.test(head) && !headKZ){ str=paren[1].trim(); }
  else { str=str.replace(/\s*\([^)]*\)\s*$/, function(m){return /[А-Яа-яЁё]/.test(m)?m:'';}).trim(); }
  var person=null;
  var m=str.match(/\s+им(?:ени|\.)\s+(.+)$/i);
  if(m){person=m[1].trim();str=str.slice(0,m.index).trim();}
  var rep=[
    [/Западно-Казахстанск(ий|ая|ого)/gi,'Батыс Қазақстан'],[/Восточно-Казахстанск(ий|ая|ого)/gi,'Шығыс Қазақстан'],[/Южно-Казахстанск(ий|ая|ого)/gi,'Оңтүстік Қазақстан'],[/Северо-Казахстанск(ий|ая|ого)/gi,'Солтүстік Қазақстан'],[/Центрально-Казахстанск(ий|ая|ого)/gi,'Орталық Қазақстан'],
    [/Казахстанско-Российск(ий|ого)/gi,'Қазақстан-Ресей'],[/Казахстанско-Американск(ий|ого)/gi,'Қазақстан-Америка'],[/Казахстанско-Британск(ий|ого)/gi,'Қазақстан-Британ'],
    [/Карагандинск(ий|ого)/gi,'Қарағанды'],[/Алматинск(ий|ого)/gi,'Алматы'],[/Костанайск(ий|ого)/gi,'Қостанай'],[/Кустанайск(ий|ого)/gi,'Қостанай'],[/Актюбинск(ий|ого)/gi,'Ақтөбе'],[/Атырауск(ий|ого)/gi,'Атырау'],[/Кызылординск(ий|ого)/gi,'Қызылорда'],[/Жамбылск(ий|ого)/gi,'Жамбыл'],[/Таразск(ий|ого)/gi,'Тараз'],[/Шымкентск(ий|ого)/gi,'Шымкент'],[/Семейск(ий|ого)/gi,'Семей'],[/Кокшетауск(ий|ого)/gi,'Көкшетау'],[/Петропавловск(ий|ого)/gi,'Петропавл'],[/Уральск(ий|ого)/gi,'Орал'],[/Аркалыкск(ий|ого)/gi,'Арқалық'],[/Павлодарск(ий|ого)/gi,'Павлодар'],[/Туркестанск(ий|ого)/gi,'Түркістан'],[/Жезказганск(ий|ого)/gi,'Жезқазған'],[/Жетысуск(ий|ого)/gi,'Жетісу'],[/Рудненск(ий|ого)/gi,'Рудный'],[/Екибастузск(ий|ого)/gi,'Екібастұз'],
    [/Казахстанск(ий|ая|ого)/gi,'Қазақстан'],[/Каз[аa]хск(ий|ая|ого)/gi,'Қазақ'],[/Казахская/gi,'Қазақ'],
    [/национальн(ый|ая|ого|ой)/gi,'ұлттық'],[/государственн(ый|ая|ого|ой)/gi,'мемлекеттік'],[/Региональн(ый|ого)/gi,'өңірлік'],[/региональн(ый|ого)/gi,'өңірлік'],
    [/инженерно-технологическ(ий|ого)/gi,'инженерлік-технологиялық'],[/инженерно-техническ(ий|ого)/gi,'инженерлік-техникалық'],[/инженерно-экономическ(ий|ого)/gi,'инженерлік-экономикалық'],[/автомобильно-дорожн(ый|ого)/gi,'автомобиль-жол'],[/социально-техническ(ий|ого)/gi,'әлеуметтік-техникалық'],[/гуманитарно-экономическ(ий|ого)/gi,'гуманитарлық-экономикалық'],[/гуманитарно-техническ(ий|ая|ого)/gi,'гуманитарлық-техникалық'],[/аграрно-техническ(ий|ого)/gi,'аграрлық-техникалық'],[/транспортно-гуманитарн(ый|ого)/gi,'көлік-гуманитарлық'],[/инновационно-технологическ(ий|ого)/gi,'инновациялық-технологиялық'],
    [/агротехническ(ий|ого)/gi,'агротехникалық'],[/политехническ(ий|ого)/gi,'политехникалық'],[/технологическ(ий|ого)/gi,'технологиялық'],[/техническ(ий|ого)/gi,'техникалық'],
    [/Международн(ый|ая|ого|ой)/gi,'халықаралық'],[/Евразийск(ий|ого)/gi,'Еуразия'],
    [/медицинск(ий|ая|ого)/gi,'медициналық'],[/педагогическ(ий|ая|ого)/gi,'педагогикалық'],[/аграрн(ый|ого)/gi,'аграрлық'],[/гуманитарн(ый|ого)/gi,'гуманитарлық'],[/экономическ(ий|ого)/gi,'экономикалық'],[/юридическ(ий|ого)/gi,'заң'],[/инновационн(ый|ого|о)/gi,'инновациялық'],[/классическ(ий|ого)/gi,'классикалық'],[/исследовательск(ий|ого)/gi,'зерттеу'],[/индустриальн(ый|ого)/gi,'индустриялық'],[/финансов(ый|ого)/gi,'қаржы'],[/женск(ий|ая|ого)/gi,'қыздар'],[/свободн(ый|ого)/gi,'еркін'],[/Творческ(ий|ого)/gi,'шығармашылық'],[/гражданск(ой|ий|ого)/gi,'азаматтық'],
    [/образовательн(ая|ый|ого)/gi,'білім беру'],[/водного хозяйства и ирригации/gi,'су шаруашылығы және ирригациясы'],[/международных отношений/gi,'халықаралық қатынастар'],[/отношений/gi,'қатынастар'],[/искусств[а]?/gi,'өнер'],
    [/консерватория/gi,'консерваториясы'],[/университет(?!і)/gi,'университеті'],[/академи(я|и)(?!я?сы)/gi,'академиясы'],[/институт(?!ы)/gi,'институты'],
    [/имени/gi,'атындағы']
  ];
  rep.forEach(function(p){str=str.replace(p[0],p[1]);});
  str=str.replace(/\s+/g,' ').trim();
  if(person) str=person+' атындағы '+str;
  return str.charAt(0).toUpperCase()+str.slice(1);
}
  return kazifyUni;
})();
